using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports;using LWS.TruckSports.Editor;
namespace LWS.TruckLogRolling.Editor {
public static class LogAuthoring {
 public const string Folder="TruckLogRolling",Scene="Assets/TruckLogRolling/Scenes/TruckLogRolling.unity";
 public static void Create(){var m=SportsEventAuthoring.Begin<LogMatch>(Folder);Directory.CreateDirectory("Assets/"+Folder+"/Models");AssetDatabase.Refresh();m.setup.count=4;m.NormalizeSetup();m.feedback.clips=(AudioClip[])LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Clone();m.feedback.clips[5]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDockDiving/Audio/Exceptional cheer.wav");var contact=SportsEventAuthoring.Contact(Folder,"Real bark and tire contact",.7f,.06f);var root=new GameObject("Actually buoyant rotating timber log");root.layer=0;var proxy=Proxy();var shape=root.AddComponent<MeshCollider>();shape.sharedMesh=proxy;shape.convex=true;shape.sharedMaterial=contact;var body=root.AddComponent<Rigidbody>();body.mass=300000;body.centerOfMass=new Vector3(0,-.025f,0);body.linearDamping=.08f;body.angularDamping=.18f;body.maxLinearVelocity=14;body.maxAngularVelocity=4;body.maxDepenetrationVelocity=2;body.solverIterations=20;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.isKinematic=true;root.transform.position=new Vector3(0,-.4f,0);m.log=body;
 LogPresentationAuthoring.InstallTimber(root.transform);
 var tether=root.AddComponent<SpringJoint>();tether.autoConfigureConnectedAnchor=false;tether.anchor=Vector3.zero;tether.connectedAnchor=new Vector3(0,-.4f,0);tether.minDistance=0;tether.maxDistance=5;tether.spring=30000;tether.damper=20000;tether.enableCollision=false;m.buoyancy=root.AddComponent<SportsFloatingBody>();m.buoyancy.body=body;m.buoyancy.proxy=proxy;m.buoyancy.session=m;m.buoyancy.waterHeight=0;
 Water(m);m.fighters=new LogFighter[4];for(int i=0;i<4;i++){var truck=SportsEventAuthoring.Truck(m,Folder,"Log balance participant "+(i+1),new Vector3(0,3,(i-1.5f)*3.8f),i);SportsRallyAuthoring.FitTruck(truck);truck.body.mass*=1000;truck.motorTorque=8000;truck.brakeTorque=24000;truck.maxSpeed=7;truck.reverseSpeed=4;truck.steerAngle=32;truck.body.centerOfMass=new Vector3(0,-.06f,0);truck.body.angularDamping=.5f;truck.body.maxLinearVelocity=18;foreach(var wheel in truck.wheels){wheel.MaxLoad=truck.body.mass*9.81f*.5f;wheel.wheel.mass*=1000;wheel.spring.maxForce*=1000;wheel.damper.bumpRate*=1000;wheel.damper.reboundRate*=1000;wheel.rollingResistanceTorque*=1000;}var fighter=truck.gameObject.AddComponent<LogFighter>();fighter.match=m;fighter.truck=truck;fighter.slot=i;fighter.splash=Splash("Pooled true water entry splash "+i);m.fighters[i]=fighter;}
 m.replay=SportsRallyAuthoring.Replay(m,m.fighters.Select(f=>f.truck.transform).Concat(new[]{root.transform}).ToArray());m.replay.capacity=3000;m.broadcast=SportsEventAuthoring.Camera("Log close three-quarter broadcast");m.broadcast.view.orthographic=true;m.broadcast.Pose(Vector3.up,new Vector3(15,15,-24),58,true);m.fit=m.broadcast.gameObject.AddComponent<SportsCameraFit>();m.fit.cameraTarget=m.broadcast.view;m.fit.arenaFit=true;m.fit.arenaBounds=new Bounds(Vector3.up,new Vector3(17,7,29));m.fit.topInset=.08f;m.fit.bottomInset=.1f;m.fit.Apply();m.cameras=new[]{m.broadcast.view};SportsEventAuthoring.UI(m);SportsRallyAuthoring.CompactUI(m);SportsBroadcastAuthoring.ApplyScene();SportsEventAuthoring.Save(Folder);Validate();}
 public static Mesh Proxy(){Directory.CreateDirectory("Assets/"+Folder+"/Models");string path="Assets/"+Folder+"/Models/Metre baked buoyancy and contact hull.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh!=null)return mesh;var cylinder=GameObject.CreatePrimitive(PrimitiveType.Cylinder);var original=cylinder.GetComponent<MeshFilter>().sharedMesh;mesh=UnityEngine.Object.Instantiate(original);mesh.name="Metre-baked closed log buoyancy hull";var matrix=Matrix4x4.TRS(Vector3.zero,Quaternion.Euler(90,0,0),new Vector3(6,11,6));mesh.vertices=original.vertices.Select(v=>matrix.MultiplyPoint3x4(v)).ToArray();mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.UploadMeshData(false);UnityEngine.Object.DestroyImmediate(cylinder);AssetDatabase.CreateAsset(mesh,path);return mesh;}
 static ParticleSystem Splash(string name){var p=new GameObject(name).AddComponent<ParticleSystem>();p.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=p.main;main.loop=false;main.playOnAwake=false;main.simulationSpace=ParticleSystemSimulationSpace.World;main.startLifetime=new ParticleSystem.MinMaxCurve(.5f,1.2f);main.startSpeed=new ParticleSystem.MinMaxCurve(2,5);main.startSize=new ParticleSystem.MinMaxCurve(.15f,.45f);main.startColor=new Color(.55f,.86f,.95f,.6f);main.gravityModifier=.8f;main.maxParticles=96;var emission=p.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,32)});var shape=p.shape;shape.shapeType=ParticleSystemShapeType.Cone;shape.radius=.8f;shape.angle=60;var renderer=p.GetComponent<ParticleSystemRenderer>();renderer.sharedMaterial=SportsChaosAuthoring.Flare(Folder);renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;return p;}
 static void Water(LogMatch m){var water=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/NWH/Vehicle Physics 2/Prefabs/Water/Water.prefab"));water.name="Installed NWH pond mesh with orthographic River normal adapter";foreach(var component in water.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(component);foreach(var collider in water.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(collider);water.transform.position=Vector3.zero;var renderers=water.GetComponentsInChildren<Renderer>();var bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);water.transform.localScale=Vector3.Scale(water.transform.localScale,new Vector3(80/Mathf.Max(.1f,bounds.size.x),1,80/Mathf.Max(.1f,bounds.size.z)));var source=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckFishing/Materials/Clear fishing river.mat");if(source==null)throw new Exception("Existing orthographic River normal-map material adapter required");string path="Assets/"+Folder+"/Materials/Clear river pond surface.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(source);AssetDatabase.CreateAsset(material,path);}else{var copy=new Material(source);EditorUtility.CopySerialized(copy,material);UnityEngine.Object.DestroyImmediate(copy);}material.SetColor("_BaseColor",new Color(.055f,.32f,.4f,.85f));material.SetFloat("_BumpScale",.4f);material.mainTextureScale=Vector2.one*.11f;water.AddComponent<LWS.TruckFishing.FishingWaterFlow>();foreach(var renderer in renderers)renderer.sharedMaterial=material;var original=water.GetComponent<MeshFilter>().sharedMesh;string waterMeshPath="Assets/"+Folder+"/Models/Vendor-compatible pond flow mesh.asset";var waterMesh=AssetDatabase.LoadAssetAtPath<Mesh>(waterMeshPath);if(waterMesh==null){waterMesh=new Mesh();AssetDatabase.CreateAsset(waterMesh,waterMeshPath);}waterMesh.Clear();waterMesh.vertices=original.vertices;waterMesh.normals=original.normals;waterMesh.tangents=original.tangents;waterMesh.colors=new Color[original.vertexCount];waterMesh.SetUVs(0,original.vertices.Select(v=>new Vector2(v.x*water.transform.localScale.x,v.z*water.transform.localScale.z)).ToList());waterMesh.SetUVs(2,original.vertices.Select(v=>new Vector2(.12f,.025f)).ToList());waterMesh.SetTriangles(original.triangles,0);waterMesh.RecalculateBounds();waterMesh.UploadMeshData(false);EditorUtility.SetDirty(waterMesh);water.GetComponent<MeshFilter>().sharedMesh=waterMesh;var rendering=m.gameObject.AddComponent<LWS.TruckBaseJumping.BaseJumpRendering>();rendering.pipeline=AssetDatabase.LoadAssetAtPath<UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset>("Assets/TruckBogSnorkelling/Rendering/Bog pipeline.asset");var bed=SportsEventAuthoring.Mat(Folder,"Pebbled river bed",new Color(.2f,.27f,.2f),.08f);SportsEventAuthoring.Box("Distant pond bed",new Vector3(0,-12.5f,0),new Vector3(100,1,100),bed,SportsEventAuthoring.Contact(Folder,"Far pond bed",.6f,.05f));var surroundings=new GameObject("Installed woodland pond dressing").transform;for(int i=0;i<16;i++){float angle=i*Mathf.PI/8;var holder=new GameObject("Bounded woodland model "+i).transform;holder.SetParent(surroundings,false);holder.position=new Vector3(Mathf.Sin(angle)*42,-2,Mathf.Cos(angle)*42);LWS.TruckKeepaway.Editor.KeepawayPresentationAuthoring.Fit(holder,i%3==0?"Assets/Toon Gas Station/Prefabs/Rock_Cluster_1A.prefab":"Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Tree_03.prefab",new Vector3(9,10+i%3*3,9),0,false,Folder);}}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<LogMatch>();if(m==null){EditorSceneManager.OpenScene(Scene);m=UnityEngine.Object.FindAnyObjectByType<LogMatch>();}if(m==null||m.fighters.Length!=4||m.buoyancy==null||m.buoyancy.proxy==null||m.log.mass!=300000||m.log.GetComponent<MeshCollider>()==null||!m.log.GetComponent<MeshCollider>().convex||m.replay.sources.Length!=5)throw new Exception("Real buoyant log and replay references required");foreach(var f in m.fighters)if(f.truck.body.mass!=12000||f.truck.wheels.Any(w=>w.spring.maxForce<100000||w.MaxLoad<50000))throw new Exception("Mass-appropriate NWH truck dynamics required");if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new Exception("One Log Rolling listener required");Debug.Log("LOG_NATIVE_SCENE_VALIDATED");}
}
}
